export const demoTutorEmail = tutor => `demo.${tutor.key}@tutor.wondertutor.local`

export function validateDemoTutors(tutors = DEMO_TUTORS) {
  const keys = new Set()
  for (const tutor of tutors) {
    if (!/^[a-z]+(?:-[a-z]+)*$/.test(tutor.key) || keys.has(tutor.key)) throw new Error('Demo tutor keys must be unique and contain letters and hyphens only')
    keys.add(tutor.key)
    if (!tutor.name || !findLocation(tutor.location) || !(tutor.rate > 0) || !tutor.qualification?.[0]) throw new Error('Demo tutor has incomplete profile details: ' + tutor.key)
    if (!tutor.languages.length || tutor.languages.some(language => !LANGUAGES.includes(language))) throw new Error('Unsupported demo teaching language: ' + tutor.key)
    if (!tutor.characteristics.length || tutor.characteristics.some(style => !CHARACTERISTICS.includes(style))) throw new Error('Unsupported demo teaching style: ' + tutor.key)
    if (!tutor.subjects.length || tutor.subjects.some(row => !SUBJECTS.includes(row.subject) || !isSubjectAtLevel(row.subject, row.educationLevel) || !Number.isInteger(row.minGrade) || !Number.isInteger(row.maxGrade) || row.minGrade < 1 || row.minGrade > row.maxGrade || row.maxGrade > MAX_GRADE[row.educationLevel])) throw new Error('Unsupported demo teaching subject or grade: ' + tutor.key)
  }
}

// Insert-only: a rerun preserves existing credentials, profiles, calendars and
// moderation decisions, including changes the demonstrator made after seeding.
export async function addDemoTutors(db, passwordHash, tutors = DEMO_TUTORS) {
  validateDemoTutors(tutors)
  if (!passwordHash) throw new Error('A hashed demo password is required')
  return db.$transaction(async tx => {
    const created = [], skipped = []
    for (const [index, tutor] of tutors.entries()) {
      const email = demoTutorEmail(tutor)
      const existing = await tx.user.findUnique({ where: { email }, select: { role: true, tutor: { select: { id: true } } } })
      if (existing) {
        if (existing.role !== 'TUTOR' || !existing.tutor) throw new Error('A different account already uses the demo email: ' + email)
        skipped.push(email)
        continue
      }
      const area = findLocation(tutor.location)
      const user = await tx.user.create({ data: {
        email, passwordHash, role: 'TUTOR', fullName: tutor.name, isEmailVerified: true,
        profilePhotoUrl: null, emailReminders: false,
        tutor: { create: {
          gender: tutor.gender, bio: tutor.bio, yearsExperience: tutor.years, hourlyRate: tutor.rate,
          location: area.name, latitude: area.lat, longitude: area.lng,
          languages: tutor.languages, characteristics: tutor.characteristics,
          teachingApproach: 'Review the learner\'s current understanding\nExplain concepts with clear examples\nPractise together, then independently\nShare progress and next steps with the parent',
          offersOnline: true, offersPhysical: true, isVerified: true, verificationSubmittedAt: new Date(),
          subjects: { create: tutor.subjects },
          availability: { create: [
            { dayOfWeek: index % 2 ? 2 : 1, startTime: '16:00', endTime: '20:00', mode: 'BOTH' },
            { dayOfWeek: index % 2 ? 4 : 3, startTime: '17:00', endTime: '21:00', mode: 'BOTH' },
            { dayOfWeek: 6, startTime: '09:00', endTime: '12:00', mode: 'BOTH' },
            { dayOfWeek: 0, startTime: '14:00', endTime: '18:00', mode: 'BOTH' },
          ] },
          // Same seed:// convention as the original fixtures: demo statuses
          // only, never fabricated NRIC numbers or downloadable real documents.
          qualifications: { create: [
            { kind: 'IDENTITY', title: 'Demo identity record', documentUrl: 'seed://sample-nric', status: 'APPROVED', reviewNote: 'Fictional demo fixture; not real identity evidence.' },
            { kind: 'QUALIFICATION', title: tutor.qualification[0], institution: tutor.qualification[1], year: tutor.qualification[2], documentUrl: 'seed://sample-certificate', status: 'APPROVED', reviewNote: 'Fictional demo fixture; not real qualification evidence.' },
          ] },
        } },
      }, select: { id: true, tutor: { select: { id: true } } } })
      created.push({ userId: user.id, tutorId: user.tutor.id, email, name: tutor.name, location: area.name })
    }
    return { created, skipped }
  }, { isolationLevel: 'Serializable', timeout: 30000 })
}
